mapper.select:
SELECT id, feedback_id AS feedbackId, score, created_at AS createdAt
FROM rating
WHERE feedback_id = #{feedbackId}

SELECT f.type, COUNT(r.id) AS total_count, ROUND(AVG(r.score), 2) AS avg_score, SUM(CASE WHEN r.score <= 3 THEN 1 ELSE 0 END) AS bad_count, ROUND(SUM(CASE WHEN r.score <= 3 THEN 1 ELSE 0 END) * 100.0 / COUNT(r.id), 2) AS bad_rate FROM rating r JOIN feedback f ON r.feedback_id = f.id WHERE 1=1
AND r.created_at >= #{startDate}
AND r.created_at <= #{endDate}
GROUP BY f.type ORDER BY avg_score ASC
